def collection(name):
    c = bpy.data.collections.get(name)
    if c is None:
        c = bpy.data.collections.new(name)
        scene.collection.children.link(c)
    return c

COL_FRAME = collection("R11_FRAME")
COL_STATOR = collection("R11_STATOR")
COL_FLUX = collection("R11_FLUX")
COL_COILS = collection("R11_COILS")
COL_LENS = collection("R11_LENS")
