MAT_NUCLEUS = mat_principled("DarkNucleus", (0.008, 0.015, 0.025), 0.55, 0.18)

def add_bevel(obj, width=0.06, segments=3):
    mod = obj.modifiers.new(name="PrecisionBevel", type='BEVEL')
    mod.width = width
    mod.segments = segments
    mod.limit_method = 'ANGLE'
    mod.angle_limit = math.radians(22)
    return mod

def add_weighted_normal(obj):
    try:
        mod = obj.modifiers.new(name="WeightedNormals", type='WEIGHTED_NORMAL')
        mod.keep_sharp = True
    except Exception:
        pass

def shade_smooth_angle(obj, angle=math.radians(38)):
    if not hasattr(obj.data, "polygons"):
        return
    for p in obj.data.polygons:
        p.use_smooth = True
    # Blender 4 removed use_auto_smooth. Bevel + weighted normals handle it.

def add_cube(name, loc, scale, mat, coll, bevel=0.06, rot=(0,0,0)):
    bpy.ops.mesh.primitive_cube_add(location=loc, rotation=rot)
    o = bpy.context.active_object
    o.name = name
    o.scale = scale
    bpy.ops.object.transform_apply(location=False, rotation=False, scale=True)
    if mat:
        o.data.materials.append(mat)
    add_bevel(o, bevel, 3)
    add_weighted_normal(o)
    move_to_collection(o, coll)
    return o

def add_cylinder(name, radius, depth, loc, mat, coll, verts=96, rot=(0,0,0), bevel=0.04):
    bpy.ops.mesh.primitive_cylinder_add(vertices=verts, radius=radius, depth=depth, location=loc, rotation=rot)
    o = bpy.context.active_object
    o.name = name
    if mat:
        o.data.materials.append(mat)
    add_bevel(o, bevel, 3)
    add_weighted_normal(o)
    shade_smooth_angle(o)
    move_to_collection(o, coll)
    return o

def add_uv_sphere(name, radius, loc, mat, coll, scale=(1,1,1)):
    bpy.ops.mesh.primitive_uv_sphere_add(segments=96, ring_count=64, radius=radius, location=loc)
    o = bpy.context.active_object
    o.name = name
    o.scale = scale
    bpy.ops.object.transform_apply(location=False, rotation=False, scale=True)
    if mat:
        o.data.materials.append(mat)
    shade_smooth_angle(o)
    move_to_collection(o, coll)
    return o

def arc_prism(name, r0, r1, a0_deg, a1_deg, depth, z, mat, coll,
              steps=48, bevel=0.055, y_offset=0.0, skew=0.0):
    """
    Annular sector in XY with thickness along Z.
    Adds slight radial skew to avoid perfect HUD-ring purity.
    """
    a0 = math.radians(a0_deg)
    a1 = math.radians(a1_deg)
    verts = []
    faces = []

    for side_z in (-depth/2.0, depth/2.0):
        for i in range(steps + 1):
            t = i / steps
            a = a0 + (a1-a0) * t
            # small authored asymmetry
            ripple = 1.0 + skew * math.sin(t * math.pi)
            ro = r1 * ripple
            ri = r0 * (1.0 - 0.35 * skew * math.sin(t * math.pi))
            verts.append((ri*math.cos(a), ri*math.sin(a)+y_offset, z+side_z))
            verts.append((ro*math.cos(a), ro*math.sin(a)+y_offset, z+side_z))

    ring_count = steps + 1
    bottom = 0
    top = ring_count * 2

    # front/back
    for i in range(steps):
        i0 = bottom + i*2
        i1 = i0 + 2
        faces.append((i0, i0+1, i1+1, i1))
        j0 = top + i*2
        j1 = j0 + 2
        faces.append((j0, j1, j1+1, j0+1))

    # inner / outer walls
    for i in range(steps):
        b0 = bottom + i*2
        b1 = b0 + 2
        t0 = top + i*2
        t1 = t0 + 2
        faces.append((b0, b1, t1, t0))

        b0o = bottom + i*2 + 1
        b1o = b0o + 2
        t0o = top + i*2 + 1
        t1o = t0o + 2
        faces.append((b0o, t0o, t1o, b1o))

    # end caps
    faces.append((bottom, top, top+1, bottom+1))
    e_b = bottom + steps*2
    e_t = top + steps*2
    faces.append((e_b, e_b+1, e_t+1, e_t))

    mesh = bpy.data.meshes.new(name+"_mesh")
    mesh.from_pydata(verts, [], faces)
    mesh.update()
    o = bpy.data.objects.new(name, mesh)
    coll.objects.link(o)
    if mat:
        o.data.materials.append(mat)
    add_bevel(o, bevel, 3)
    add_weighted_normal(o)
    shade_smooth_angle(o)
    return o

def radial_box(name, angle_deg, radius, tangential, radial, depth, z, mat, coll,
               angle_offset_deg=0.0, radial_offset=0.0):
    a = math.radians(angle_deg)
    r = radius + radial_offset
    x, y = r*math.cos(a), r*math.sin(a)
    # local X=tangential, Y=radial, Z=depth
    o = add_cube(
        name,
        (x, y, z),
        (tangential/2.0, radial/2.0, depth/2.0),
        mat,
        coll,
        bevel=min(0.075, min(tangential, radial, depth)*0.12),
        rot=(0,0,a - math.pi/2.0 + math.radians(angle_offset_deg))
    )
    return o

