def render_view(filename, loc, target=(0,0,-0.15), lens=58):
    cam.location = loc
    cam.data.lens = lens
    look_at(cam, target)
    scene.render.filepath = os.path.join(RENDER_DIR, filename)
    bpy.ops.render.render(write_still=True)

