def mesh_triangles():
    total = 0
    for obj in scene.objects:
        if obj.type == 'MESH':
            # evaluated mesh count is expensive but accurate enough here
            dg = bpy.context.evaluated_depsgraph_get()
            ev = obj.evaluated_get(dg)
            me = ev.to_mesh()
            me.calc_loop_triangles()
            total += len(me.loop_triangles)
            ev.to_mesh_clear()
    return total

tri_count = mesh_triangles()

report_path = os.path.join(OUT_DIR, "R11_BUILD_REPORT.txt")
with open(report_path, "w", encoding="utf-8") as f:
    f.write("E.V. R11 VECTOR REACTOR BUILD REPORT\n")
    f.write("===================================\n\n")
    f.write(f"Blender version: {bpy.app.version_string}\n")
    f.write(f"Estimated evaluated triangle count: {tri_count}\n")
    f.write("Live EV project modified: NO\n\n")
    f.write("Renders:\n")
    for name in [
        "R11_FRONT.png",
        "R11_PRIMARY_3Q.png",
        "R11_OPPOSITE_3Q.png",
        "R11_SIDE_DEPTH.png",
        "R11_DARK_ENERGY.png",
    ]:
        f.write(f"- {os.path.join(RENDER_DIR, name)}\n")
    f.write("\nAssets:\n")
    for _, name in exports:
        p = os.path.join(ASSET_DIR, name)
        f.write(f"- {p} ({os.path.getsize(p) if os.path.exists(p) else 0} bytes)\n")

print("\nR11 VECTOR REACTOR COMPLETE")
print("Blend:", blend_path)
print("Triangle count:", tri_count)
print("Renders:", RENDER_DIR)
print("Assets:", ASSET_DIR)
print("Report:", report_path)
